/// A route-shield badge, like the ones on highway signs.
String shieldSvg(String glyph, String tone) {
  final glyphColor = tone == 'yellow' ? '#1e2b37' : '#ffffff';
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 54">'
      '<path d="$shieldPath" fill="#1e2b37" stroke="#1e2b37" stroke-width="5" stroke-linejoin="round"/>'
      '<path d="$shieldPath" fill="${shieldFill[tone] ?? '#175089'}" stroke="#ffffff" stroke-width="2" stroke-linejoin="round"/>'
      '<g transform="translate(12 13.5)" fill="none" stroke="$glyphColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">'
      '${glyphInner[glyph] ?? ''}</g></svg>';
}
